"""Static catalog of software components, keyed by catalog display_id.

GENERATED by scripts/build_def_components.py. Do not edit by hand; change the
inputs (defs/catalog-tagging.html, defs/os_non_os_v3.2/*.json,
db/cve_to_prereq_with_ids.csv, defs/def_eol.py) and regenerate.

Two independent tags (logic v2):
  role             is the component the whole OS or firmware itself?
                   OS / FIRMWARE come from the catalog roles `os` and `firmware`
                   (strict: os-kernel, os-service, ... are OTHER).
  remediation_tag  is the component fixed by an OS / firmware update (OS),
                   by its own vendor patch (NON_OS), or not processed (IGNORE).
"""

from dataclasses import dataclass
from enum import Enum


class Role(Enum):
    """Catalog role, reduced to what the engine decides on.

    OS        the whole operating system (fixed by an OS update)
    FIRMWARE  device firmware or appliance OS (fixed by a firmware update)
    OTHER     everything else; routed by its remediation tag
    """

    OS = "os"
    FIRMWARE = "firmware"
    OTHER = "other"


class RemediationTag(Enum):
    """How a component is fixed."""

    OS = "OS"
    NON_OS = "Non-OS"
    IGNORE = "Ignore"


@dataclass(frozen=True, slots=True)
class SoftwareComponent:
    """One catalog component.

    catalog_record_id  catalog record uuid
    display_id         catalog display id; prerequisite files refer to it
    display_name       catalog display name
    description        catalog description
    catalog_role       the catalog's own role (os-kernel, application, ...)
    role               reduced role (see Role)
    remediation_tag    OS / NON_OS / IGNORE; None when untagged
    eol_slug           endoflife.date product slug; None when not on the site
    discontinued       end-of-life with no successor: remove, do not upgrade
    """

    catalog_record_id: str
    display_id: str
    display_name: str
    description: str
    catalog_role: str | None
    role: Role
    remediation_tag: RemediationTag | None
    eol_slug: str | None
    discontinued: bool

    @property
    def name(self) -> str:
        """Catalog display name (same as display_name)."""
        return self.display_name


